<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue';
import {onBeforeRouteLeave} from 'vue-router';
import {useI18n} from 'vue-i18n';
import {useAuthStore} from '../../stores/auth';
import {operationRequest} from '../../services/admin/operations';
import {cmsRequest} from '../../services/cms/admin';
import {refreshPublished,media} from '../../services/cms/content';
import {emptyText,catalogPriceText,type ServiceCatalog} from '../../services/cms/serviceCatalog';
import {seoBaseline} from '../../services/seo';
import {suggestSlug} from '../../services/admin/slug';
import {trapDialogFocus} from '../../services/dialogFocus';
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue';
import AdminMediaPreview from '../../components/admin/AdminMediaPreview.vue';
import MediaLibrary from '../../components/admin/MediaLibrary.vue';
const {t,locale}=useI18n(),auth=useAuthStore(),c=new AbortController(),data=ref<ServiceCatalog|null>(null),version=ref(0),busy=ref(false),error=ref(''),notice=ref(''),query=ref(''),tab=ref('services'),archived=ref(false),language=ref<'lv'|'ru'|'en'>('lv');
const draft=ref<ServiceCatalog|null>(null),kind=ref(''),selected=ref(''),invalid=ref(''),picker=ref<HTMLDialogElement>(),picking=ref(false);
const service=computed(()=>draft.value?.services.find(s=>s.id===selected.value));
const category=computed(()=>draft.value?.categories.find(s=>s.id===selected.value));
const price=computed(()=>draft.value?.categories.flatMap(c=>c.items).find(p=>p.id===selected.value));
const current=computed<any>(()=>service.value||price.value||category.value);
const title=computed(()=>service.value?.title||price.value?.name||category.value?.title);
const servicePrice=computed(()=>draft.value?.categories.flatMap(c=>c.items).find(p=>p.id===service.value?.price_id));
const shown=computed(()=>data.value?.services.filter(s=>s.archived===archived.value&&s.title[locale.value as 'lv'].toLowerCase().includes(query.value.toLowerCase()))||[]);
const operations=ref<any[]>([]),doctors=ref<any[]>([]),bookingForm=ref<any>(null),approved=ref(false);
let loaded=false;
async function load(){busy.value=true;error.value='';try{const r=await cmsRequest('/catalog',c.signal);data.value=r.catalog;version.value=r.version;loaded=true;const [ops,staff]=await Promise.all([operationRequest('/operations/services',c.signal),operationRequest('/operations/doctors',c.signal)]);operations.value=ops.items;doctors.value=staff.items}catch{error.value='unavailable'}finally{busy.value=false}}
watch(()=>auth.verifiedAdmin,v=>{if(v&&!loaded)void load()},{immediate:true});
function edit(type:string,id:string){draft.value=JSON.parse(JSON.stringify(data.value));kind.value=type;selected.value=id;language.value=locale.value as 'lv';invalid.value='';error.value='';notice.value='';bookingForm.value=null;approved.value=false;const s=draft.value?.services.find(s=>s.id===id);const op=operations.value.find(o=>o.id===s?.booking_id);if(op){const d=op.data;bookingForm.value={slug:d.slug,name_lv:d.name_lv,name_ru:d.name_ru,name_en:d.name_en,description_lv:d.description_lv,description_ru:d.description_ru,description_en:d.description_en,duration_minutes:d.duration_minutes,price_display_lv:d.price_display_lv,price_display_ru:d.price_display_ru,price_display_en:d.price_display_en,active:d.active,booking_enabled:d.booking_enabled,sort_order:d.sort_order,provenance:d.provenance,editorial_key:d.editorial_key||'',assignments:JSON.parse(JSON.stringify(d.assignments||[]))}}}
function add(type:string,categoryID?:string){edit(type,'');const id=crypto.randomUUID();if(type==='service'){selected.value='service.'+id;draft.value!.services.push({id:selected.value,booking_id:'',slug:'',title:emptyText(),short:emptyText(),text:emptyText(),image:'',category:draft.value!.categories[0]?.id||'',price_id:'',published:true,archived:false})}else if(type==='category'){selected.value='category.'+id;draft.value!.categories.push({id:selected.value,title:emptyText(),concession:false,items:[]})}else{selected.value='price.'+id;draft.value!.categories.find(c=>c.id===categoryID)!.items.push({id:selected.value,name:emptyText(),price:'',type:'fixed',archived:false,display_order:draft.value!.categories.find(c=>c.id===categoryID)!.items.length})}}
function addServicePrice(){const s=service.value!;const cat=draft.value!.categories.find(c=>c.id===s.category);if(!cat)return;const id='price.'+crypto.randomUUID();cat.items.push({id,name:JSON.parse(JSON.stringify(s.title)),price:'',type:'fixed',archived:false,display_order:cat.items.length});s.price_id=id}
function cancel(){if(!draft.value||window.confirm(t('catalog.discard'))){draft.value=null;invalid.value='';error.value=''}}
async function bad(field:string,lang?:'lv'|'ru'|'en'){invalid.value=field;if(lang)language.value=lang;await nextTick();document.getElementById('catalog-'+field)?.focus()}
async function save(){if(!draft.value||busy.value)return;invalid.value='';for(const l of ['lv','ru','en'] as const){if(!title.value?.[l].trim()||new TextEncoder().encode(title.value[l]).length>(service.value?200:2000)||/<[^>]+>/.test(title.value[l]))return bad('name',l);if(service.value&&(!service.value.text[l].trim()||new TextEncoder().encode(service.value.text[l]).length>12000||/<[^>]+>/.test(service.value.text[l])))return bad('description',l)}
 if(service.value&&!service.value.category)return bad('category');const p=price.value||servicePrice.value;if(p&&['fixed','from'].includes(p.type))p.price=p.price.replace(',','.');if(p&&p.type!=='consultation'&&(!p.price.trim()||(['fixed','from'].includes(p.type)&&!/^\d{1,7}(\.\d{1,2})?$/.test(p.price))))return bad('price');if(p?.type==='consultation')p.price='consultation';
 if(service.value&&servicePrice.value&&!data.value?.categories.some(c=>c.items.some(p=>p.id===servicePrice.value!.id)))servicePrice.value.name=JSON.parse(JSON.stringify(service.value.title));
 if(service.value&&!service.value.slug)service.value.slug=suggestSlug(service.value.title.lv);
 busy.value=true;error.value='';try{await cmsRequest('/catalog',c.signal,{expected_version:version.value,catalog:draft.value},'POST');draft.value=null;notice.value=t('catalog.done');await refreshPublished(true);await load()}catch(e){error.value=(e as Error).message;const field=(e as Error&{field?:string}).field;if(field)await bad(field==='service'?'name':field)}finally{busy.value=false;await nextTick();if(invalid.value)document.getElementById('catalog-'+invalid.value)?.focus()}}
async function archive(type:string,id:string){if(!window.confirm(t('catalog.confirm')))return;edit(type,id);current.value.archived=!current.value.archived;await save()}
async function move(categoryID:string,id:string,delta:number){draft.value=JSON.parse(JSON.stringify(data.value));const rows=draft.value!.categories.find(c=>c.id===categoryID)!.items;const order=[...rows].sort((a,b)=>a.display_order-b.display_order),i=order.findIndex(p=>p.id===id),j=i+delta;if(j<0||j>=order.length){draft.value=null;return};[order[i],order[j]]=[order[j]!,order[i]!];order.forEach((r,i)=>r.display_order=i);kind.value='price';selected.value=id;await save()}
function imageSelect(asset:any){if(service.value)service.value.image=asset.origin==='upload'?'cms-media:'+asset.id:asset.url;closePicker()}
function closePicker(){picker.value?.close();picking.value=false}

function bookingEnabled(id:string){const d=operations.value.find(o=>o.id===id)?.data;return !!(d?.active&&d?.booking_enabled&&d?.duration_minutes)}
function setSEO(field:'seo_title'|'seo_description',value:string){if(service.value){service.value[field]??=emptyText();service.value[field]![language.value]=value}}
function prepareBooking(){if(service.value)service.value.booking_id=crypto.randomUUID()}
function assigned(id:string){return bookingForm.value?.assignments.some((a:any)=>a.doctor_id===id&&a.booking_enabled)}
function assign(id:string,value:boolean){const a=bookingForm.value.assignments.find((a:any)=>a.doctor_id===id);if(a)a.booking_enabled=value;else bookingForm.value.assignments.push({doctor_id:id,booking_enabled:value,duration_override_minutes:null})}
async function saveBooking(){if(!service.value?.booking_id||!bookingForm.value||!approved.value)return;if(JSON.stringify(draft.value)!==JSON.stringify(data.value)){error.value='saveEditorialFirst';return;}const op=operations.value.find(o=>o.id===service.value!.booking_id);busy.value=true;error.value='';try{await operationRequest('/operations/services/'+op.id,c.signal,{operation_id:crypto.randomUUID(),expected_version:op.version,data:{...bookingForm.value,duration_approved:true}},'PUT');draft.value=null;notice.value=t('catalog.done');await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}

function beforeUnload(e:BeforeUnloadEvent){if(draft.value){e.preventDefault();e.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload);onBeforeRouteLeave(()=>!draft.value||window.confirm(t('catalog.discard')));onBeforeUnmount(()=>{c.abort();window.removeEventListener('beforeunload',beforeUnload)});
</script>
<template><section class="catalog-admin"><AdminPageHeader :title="t('catalog.title')"/>
<p v-if="error" role="alert">{{t('catalog.'+(['conflict','invalid','saveEditorialFirst','notReady'].includes(error)?error:'unavailable'))}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="busy" role="status">{{t('newsAdmin.loading')}}</p>
<template v-if="data&&!draft"><div class="toolbar"><button @click="tab='services'" :aria-pressed="tab==='services'">{{t('catalog.services')}}</button><button @click="tab='prices'" :aria-pressed="tab==='prices'">{{t('catalog.prices')}}</button><button class="primary" @click="add(tab==='services'?'service':'category')">{{t(tab==='services'?'catalog.add':'catalog.addCategory')}}</button></div><label><input type="checkbox" v-model="archived"/> {{t('catalog.archived')}}</label>
<template v-if="tab==='services'"><label>{{t('catalog.search')}}<input v-model="query" type="search"/></label><p v-if="!shown.length">{{t('catalog.empty')}}</p><article v-for="s in shown" :key="s.id" class="catalog-row"><div><h2>{{s.title[locale as 'lv']}}</h2><p>{{data.categories.find(c=>c.id===s.category)?.title[locale as 'lv']}}</p><p>{{s.published?t('catalog.published'):t('catalog.hidden')}} · {{t(bookingEnabled(s.booking_id)?'catalog.bookingEnabled':'catalog.notBooking')}}</p><p v-for="p in data.categories.flatMap(c=>c.items).filter(p=>p.id===s.price_id&&!p.archived)" :key="p.id">{{catalogPriceText(p,locale)}}</p></div><div class="actions"><button @click="edit('service',s.id)">{{t('catalog.edit')}}</button><button :disabled="busy" @click="archive('service',s.id)">{{t(s.archived?'catalog.restore':'catalog.archive')}}</button></div></article></template>
<template v-else><section v-for="cat in data.categories" :key="cat.id"><div class="toolbar"><h2>{{cat.title[locale as 'lv']}}</h2><button @click="edit('category',cat.id)">{{t('catalog.edit')}}</button><button @click="add('price',cat.id)">{{t('catalog.addPrice')}}</button></div><article v-for="p in [...cat.items].sort((a,b)=>a.display_order-b.display_order).filter(p=>p.archived===archived)" :key="p.id" class="catalog-row"><div>{{p.name[locale as 'lv']}}<p>{{catalogPriceText(p,locale)}}</p></div><div class="actions"><button @click="edit('price',p.id)">{{t('catalog.edit')}}</button><button :disabled="busy" @click="archive('price',p.id)">{{t(p.archived?'catalog.restore':'catalog.archive')}}</button><button :disabled="busy" @click="move(cat.id,p.id,-1)">{{t('catalog.up')}}</button><button :disabled="busy" @click="move(cat.id,p.id,1)">{{t('catalog.down')}}</button></div></article></section></template></template>
<form v-if="draft&&current" novalidate @submit.prevent="save"><fieldset :disabled="busy"><div class="toolbar"><button class="primary" type="submit">{{t('catalog.save')}}</button><button type="button" @click="cancel">{{t('catalog.cancel')}}</button></div><label>{{t('catalog.language')}}<select v-model="language"><option v-for="l in ['lv','ru','en']" :key="l">{{l}}</option></select></label><label>{{t('catalog.name')}} *<input id="catalog-name" v-model="title![language]" :aria-invalid="invalid==='name'" maxlength="200"/></label><p v-if="invalid==='name'" role="alert">{{t('catalog.required')}}</p>
<template v-if="service"><label>{{t('catalog.description')}} *<textarea id="catalog-description" v-model="service.text[language]" rows="7" :aria-invalid="invalid==='description'" maxlength="10000"/></label><p v-if="invalid==='description'" role="alert">{{t('catalog.required')}}</p><label>{{t('catalog.short')}}<textarea v-model="service.short[language]" rows="2" maxlength="1000"/></label><details v-if="!seoBaseline['/pakalpojumi/'+service.slug]"><summary>{{t('catalog.seo')}}</summary><label>{{t('catalog.seoTitle')}}<input :value="service.seo_title?.[language]||''" @input="setSEO('seo_title',($event.target as HTMLInputElement).value)" maxlength="200"/></label><label>{{t('catalog.seoDescription')}}<textarea :value="service.seo_description?.[language]||''" @input="setSEO('seo_description',($event.target as HTMLTextAreaElement).value)" maxlength="1000"/></label></details><label>{{t('catalog.category')}} *<select id="catalog-category" v-model="service.category" @change="service.price_id=''" :aria-invalid="invalid==='category'"><option v-for="cat in draft.categories" :key="cat.id" :value="cat.id">{{cat.title[locale as 'lv']}}</option></select></label><label>{{t('catalog.price')}}<select v-model="service.price_id"><option value="">{{t('catalog.none')}}</option><option v-for="p in draft.categories.find(c=>c.id===service!.category)?.items.filter(p=>!p.archived)" :key="p.id" :value="p.id">{{p.name[locale as 'lv']}}</option></select></label><button v-if="!service.price_id" type="button" @click="addServicePrice">{{t('catalog.addPrice')}}</button><label><input type="checkbox" v-model="service.published"/> {{t('catalog.published')}}</label><button id="catalog-image" type="button" @click="picking=true;picker?.showModal()">{{t('catalog.image')}}</button><AdminMediaPreview v-if="service.image" :reference="(media as Record<string,string>)[service.image]||service.image"/><button v-if="service.image" type="button" @click="service.image=''">{{t('catalog.removeImage')}}</button><p>{{t('catalog.bookingNote')}}</p><details v-if="!service.booking_id&&data?.services.some(s=>s.id===service!.id)"><summary>{{t('catalog.prepareBooking')}}</summary><label>{{t('catalog.linkExisting')}}<select v-model="service.booking_id"><option value="">{{t('operations.choose')}}</option><option v-for="op in operations.filter(o=>!draft!.services.some(s=>s.booking_id===o.id)&&(!o.data.editorial_key||o.data.editorial_key===service!.id))" :key="op.id" :value="op.id">{{op.data['name_'+locale]}}</option></select></label><button type="button" @click="prepareBooking()">{{t('catalog.prepareBooking')}}</button></details><details v-if="bookingForm"><summary>{{t('operations.booking')}}</summary><label>{{t('operations.duration')}}<input type="number" min="1" max="1440" v-model.number="bookingForm.duration_minutes"/></label><label v-for="d in doctors" :key="d.id"><input type="checkbox" :checked="assigned(d.id)" @change="assign(d.id,($event.target as HTMLInputElement).checked)"/> {{d.data.name}}</label><label><input type="checkbox" v-model="bookingForm.active"/> {{t('operations.active')}}</label><label><input type="checkbox" v-model="bookingForm.booking_enabled"/> {{t('operations.booking')}}</label><label><input type="checkbox" v-model="approved"/> {{t('catalog.approvedDuration')}}</label><button type="button" :disabled="!approved||busy" @click="saveBooking">{{t('catalog.saveBooking')}}</button></details></template>
<template v-if="price||servicePrice"><label>{{t('catalog.type')}}<select v-model="(price||servicePrice)!.type"><option v-for="type in ['fixed','from','consultation','text']" :key="type" :value="type">{{t('catalog.'+type)}}</option></select></label><label v-if="(price||servicePrice)!.type!=='consultation'">{{t('catalog.price')}} *<input id="catalog-price" v-model="(price||servicePrice)!.price" :aria-invalid="invalid==='price'" maxlength="200"/></label><p v-if="invalid==='price'" role="alert">{{t('catalog.priceInvalid')}}</p></template></fieldset></form>
<dialog ref="picker" @keydown="trapDialogFocus" @cancel.prevent="closePicker" :aria-label="t('catalog.image')"><MediaLibrary v-if="picking" picker @select="imageSelect" @close="closePicker"/></dialog></section></template>
<style scoped>
.catalog-admin{max-width:1100px}.toolbar,.actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:16px 0}.toolbar h2{margin-right:auto}.catalog-row{display:flex;justify-content:space-between;gap:24px;padding:20px 0;border-bottom:1px solid var(--line)}h2{font:400 26px/1.3 var(--serif)}button{min-height:44px;padding:10px 14px;background:transparent;border:1px solid var(--line);color:var(--ink);font:inherit;cursor:pointer}.primary{background:var(--olive);color:var(--white)}button:disabled{opacity:.5}label{display:block;margin:16px 0}input:not([type=checkbox]),textarea,select{display:block;width:100%;min-height:44px;background:var(--white);color:var(--ink);border:1px solid var(--line);padding:10px;font:inherit}fieldset{padding:0;border:0;min-width:0}form{max-width:760px}[role=alert]{color:#8b3429}:focus-visible{outline:2px solid var(--olive);outline-offset:3px}dialog{margin:auto;width:min(1000px,95vw);max-height:90dvh;background:var(--paper);border:1px solid var(--line);padding:16px}@media(max-width:650px){.catalog-row{display:block}.actions{gap:8px}}
</style>
